import{_ as d,c as t,o,ad as c}from"./chunks/framework.DGbM31vj.js";const p=JSON.parse('{"title":"MCP 命令","description":"","frontmatter":{"title":"MCP 命令"},"headers":[],"relativePath":"feature/mcp/commands.md","filePath":"feature/mcp/commands.md","lastUpdated":1788143555000}'),a={name:"feature/mcp/commands.md"};function r(n,e,s,_,l,i){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="mcp-命令" tabindex="-1">MCP 命令 <a class="header-anchor" href="#mcp-命令" aria-label="Permalink to &quot;MCP 命令&quot;">​</a></h1><p>MCP 中的“命令”以工具（tool）的形式提供。调用时由 AI 客户端传入 JSON 参数。</p><h2 id="应用配置" tabindex="-1">应用配置 <a class="header-anchor" href="#应用配置" aria-label="Permalink to &quot;应用配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>主要参数</th><th>用途</th></tr></thead><tbody><tr><td><code>get_config</code></td><td>无</td><td>获取可配置字段的 schema、当前值和解析后的生效值；密码、Cookie、Token 等敏感字段不返回明文。</td></tr><tr><td><code>update_config</code></td><td><code>values</code></td><td>批量校验并保存非只读配置；实际值发生变化后自动安排应用优雅重启。</td></tr><tr><td><code>get_restart_status</code></td><td><code>restart_token</code></td><td>在连接恢复后确认是否已切换到新进程，以及新进程加载的配置是否与保存结果一致。</td></tr></tbody></table><p><code>get_config</code> 将 <code>internal/config/config.go</code> 注册的应用配置放在 <code>application_fields</code>，将 adapter 提供的配置放在 <code>plugin_fields</code>，并在兼容字段 <code>fields</code> 中返回两者合集。每个字段还带有 <code>source</code>；插件字段额外带有 <code>namespace</code>。</p><p><code>update_config</code> 的键必须来自 <code>get_config</code>。值必须符合字段类型和 <code>options</code> 枚举约束。配置文件使用原子替换方式保存；成功响应中的 <code>restart_scheduled: true</code> 只表示重启已经安排，不能据此宣称重启完成。调用方必须保存 <code>restart_token</code>，在连接恢复后调用 <code>get_restart_status</code>。只有响应同时满足 <code>status: &quot;completed&quot;</code>、<code>restart_completed: true</code> 和 <code>config_applied: true</code>，才能确认新进程已经运行且保存后的配置已经加载。<code>pending</code> 需要继续重试，<code>failed</code> 表示重启请求失败，<code>config_mismatch</code> 表示进程已更换但配置摘要不一致。</p><p>重启期间 HTTP、WebSocket 和 MCP 连接可能短暂断开，客户端应重新连接。若修改了 <code>api.hostname</code> 或 <code>api.port</code>，应改用新地址连接；stdio 客户端也需要更新 API 地址或重新启动。提交的值与当前值完全相同时不会写盘或重启。</p><h2 id="worker-部署" tabindex="-1">Worker 部署 <a class="header-anchor" href="#worker-部署" aria-label="Permalink to &quot;Worker 部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>主要参数</th><th>用途</th></tr></thead><tbody><tr><td><code>deploy_sph_worker</code></td><td>无</td><td>从应用配置读取 Cloudflare 凭证，部署或覆盖视频号查询 Worker，并返回 workers.dev 地址。</td></tr></tbody></table><p><code>deploy_sph_worker</code> 读取 <code>cloudflare.accountId</code>、<code>cloudflare.apiToken</code>、<code>cloudflare.sphWorkerName</code>、<code>cloudflare.sphCookie</code> 和 <code>cloudflare.sphCredential</code>，不会通过 MCP 参数传输这些敏感值。调用会覆盖同名远端 Worker，因此必须先获得用户确认。<code>get_config</code> 可用时，可先检查这些字段的 <code>configured</code> 状态。</p><h2 id="内容解析与下载" tabindex="-1">内容解析与下载 <a class="header-anchor" href="#内容解析与下载" aria-label="Permalink to &quot;内容解析与下载&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>主要参数</th><th>用途</th></tr></thead><tbody><tr><td><code>get_platform_status</code></td><td>无</td><td>获取支持的平台及其当前可用状态。</td></tr><tr><td><code>fetch_content</code></td><td><code>url</code>；可选 <code>force_refresh</code>、<code>timeout_seconds</code></td><td>解析内容链接，返回规范化内容、下载预览和可复用的 <code>job_id</code>。</td></tr><tr><td><code>download_content</code></td><td><code>job_id</code>、兼容参数 <code>fetch_id</code> 或 <code>url</code> 三选一</td><td>创建并启动下载任务；支持目录、文件名、视频规格、重复任务策略和等待完成等参数。</td></tr><tr><td><code>decrypt_wxchannels_video</code></td><td><code>file_path</code>、<code>key</code></td><td>原地解密由第三方下载器保存的视频号视频。</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">写文件操作</p><p><code>download_content</code> 会写入下载目录，调用前应先确认下载目标和覆盖策略。<code>existing_action: &quot;overwrite&quot;</code> 会覆盖已有任务及文件。<code>decrypt_wxchannels_video</code> 会原地覆盖指定文件，只能在 <code>fetch_content</code> 返回 <code>requires_decryption: true</code> 时使用。</p></div><h2 id="微信视频号" tabindex="-1">微信视频号 <a class="header-anchor" href="#微信视频号" aria-label="Permalink to &quot;微信视频号&quot;">​</a></h2><p>这些工具通过已打开的视频号页面访问微信接口。先调用 <code>get_wxchannels_status</code>，确认返回的 <code>available</code> 为 <code>true</code>。</p><table tabindex="0"><thead><tr><th>工具</th><th>主要参数</th><th>用途</th></tr></thead><tbody><tr><td><code>get_wxchannels_status</code></td><td>无</td><td>检查视频号页面是否已连接。</td></tr><tr><td><code>search_wxchannels_accounts</code></td><td><code>keyword</code>，可选 <code>next_marker</code></td><td>搜索视频号账号。</td></tr><tr><td><code>get_wxchannels_account_videos</code></td><td><code>username</code>，可选 <code>next_marker</code></td><td>获取账号发布的视频列表。</td></tr><tr><td><code>get_wxchannels_live_replays</code></td><td><code>username</code>，可选 <code>next_marker</code></td><td>获取账号的直播回放。</td></tr><tr><td><code>get_wxchannels_interacted_videos</code></td><td>可选 <code>flag</code>、<code>next_marker</code></td><td>获取当前用户赞过或收藏的视频，<code>flag</code> 默认值为 <code>7</code>。</td></tr><tr><td><code>get_wxchannels_followed_accounts</code></td><td>可选 <code>next_marker</code></td><td>获取当前用户关注的视频号账号。</td></tr><tr><td><code>get_wxchannels_play_history</code></td><td>可选 <code>next_marker</code></td><td>获取当前用户最近的视频号播放记录。</td></tr><tr><td><code>get_wxchannels_video_profile</code></td><td><code>url</code>，或 <code>oid</code> + <code>nid</code>，或 <code>eid</code></td><td>获取单个视频详情。</td></tr><tr><td><code>get_wxchannels_video_comments</code></td><td><code>oid</code> + <code>nid</code>，或 <code>oid</code> + <code>comment_id</code>；可选 <code>next_marker</code></td><td>获取一级评论或指定根评论的回复。</td></tr><tr><td><code>get_wxchannels_video_share_url</code></td><td><code>oid</code></td><td>获取视频的 H5 分享链接。</td></tr></tbody></table><p>列表工具会保留微信接口的分页字段。继续翻页时，将上一页 <code>data.lastBuffer</code> 原样传给 <code>next_marker</code>；只有账号搜索使用 <code>data.lastBuff</code>。游标不需要解码或修改。</p><h2 id="本地数据" tabindex="-1">本地数据 <a class="header-anchor" href="#本地数据" aria-label="Permalink to &quot;本地数据&quot;">​</a></h2><p>本地数据工具均为只读，并支持用筛选参数减少返回量。Streamable HTTP 直接使用当前进程中的数据库与运行时服务；stdio 则通过下载器 API 查询相同数据。</p><table tabindex="0"><thead><tr><th>工具</th><th>主要参数</th><th>用途</th></tr></thead><tbody><tr><td><code>get_download_tasks</code></td><td><code>page</code>、<code>page_size</code>、<code>statuses</code>、<code>parent_task_id</code>、<code>root_task_id</code></td><td>分页获取下载任务和状态统计。状态 <code>0</code> 至 <code>7</code> 分别表示等待、准备、下载中、暂停、合并、完成、失败、取消。</td></tr><tr><td><code>get_download_task_detail</code></td><td><code>id</code></td><td>获取任务、文件、进度、关联内容和账号详情。</td></tr><tr><td><code>get_accounts</code></td><td><code>page</code>、<code>page_size</code>、<code>keyword</code>、<code>account_id</code></td><td>分页查询数据库中的平台账号。</td></tr><tr><td><code>get_browse_history</code></td><td><code>page</code>、<code>page_size</code>、<code>keyword</code>、<code>username</code>、<code>platform_ids</code></td><td>分页查询浏览记录；<code>username</code> 是数据库账号 ID，例如 <code>wxchannels:xxx</code>。</td></tr><tr><td><code>get_logs</code></td><td><code>page</code>、<code>page_size</code>、<code>max_bytes</code>、<code>keyword</code>、<code>source</code>、<code>levels</code>、<code>format_json</code></td><td>分页读取并筛选应用日志。</td></tr><tr><td><code>get_certificate_status</code></td><td>无</td><td>获取代理根证书的来源、安装、信任状态和风险提示。</td></tr></tbody></table>',20)])])}const u=d(a,[["render",r]]);export{p as __pageData,u as default};
